fn transpose(arr: Vec<Vec<i8>>) -> Vec<Vec<i8>> {
    let rows = arr.len();
    let cols = arr[0].len();
    
    // Create output matrix with swapped dimensions
    let mut result = vec![vec![0i8; rows]; cols];
    
    // Fill the transposed matrix
    for i in 0..rows {
        for j in 0..cols {
            result[j][i] = arr[i][j];
        }
    }
    
    result
}